<script lang="ts">import Modal from '../common/Modal.svelte';import { previewImport,importVocabulary } from '../../api/import';let { blockId,onclose,onimported }=$props<{blockId:string;onclose:()=>void;onimported:(count:number)=>void}>();let json=$state(''),errors=$state<string[]>([]),valid=$state(0),busy=$state(false);async function validate(){try{const r=await previewImport(json);errors=r.errors;valid=r.validCount}catch(e){errors=[(e as Error).message];valid=0}}async function run(){busy=true;try{const r=await importVocabulary(blockId,json);onimported(r.importedCount)}catch(e){errors=[(e as Error).message]}finally{busy=false}}</script>
<Modal title="Import vocabulary JSON" {onclose}><div class="stack"><p>Paste an object containing an <code>entries</code> array. Required fields are validated before a transactional import.</p><textarea bind:value={json} spellcheck="false" placeholder="Paste vocabulary JSON here"></textarea>{#if errors.length}<div class="errors">{#each errors as error}<div>{error}</div>{/each}</div>{:else if valid}<div class="valid">Ready to import {valid} entries.</div>{/if}<footer><button class="ghost" onclick={validate} disabled={!json.trim()}>Validate</button><button class="primary" onclick={run} disabled={!json.trim()||busy}>{busy?'Importing…':'Import all valid entries'}</button></footer></div></Modal>
<style>.stack{display:grid;gap:14px}.stack>p{font-size:13px;color:var(--text-muted);line-height:1.5}textarea{min-height:330px;resize:vertical;font-family:Consolas,monospace;font-size:12px;line-height:1.55}.errors,.valid{max-height:120px;overflow:auto;padding:11px 12px;border-radius:9px;font-size:12px}.errors{color:#aa3041;background:#d8485b0d;border:1px solid #d8485b33}.valid{color:#176747;background:#24845f0d;border:1px solid #24845f33}footer{display:flex;justify-content:flex-end;gap:10px}</style>
